        yield return new("shape", Shape);
        yield return new("dot_size", DotSize);
        yield return new("background", Background);
        yield return new("margin", Margin);
        yield return new("version", Version);
        yield return new("mode", Mode);
        yield return new("mask", Mask);
        yield return new("unit", Unit);
        yield return new("xml_declaration", XmlDeclaration);
        yield return new("aria_label", AriaLabel);
        yield return new("title", Title);
        yield return new("desc", Desc);
        yield return new("format", Format);
        yield return new("share", Share);
        yield return new("fields", Fields);
